import{_ as i,c as r,o as s,ae as t}from"./chunks/framework.Bw0Gm4PQ.js";const p=JSON.parse('{"title":"Restoring Public Service Loan Forgiveness","description":"","frontmatter":{"title":"Restoring Public Service Loan Forgiveness","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/03/restoring-public-service-loan-forgiveness/","publishDate":"2025-03-07T21:31:36-05:00"},"headers":[],"relativePath":"executive-orders/2025-03-08-restoring-public-service-loan-forgiveness.md","filePath":"executive-orders/2025-03-08-restoring-public-service-loan-forgiveness.md"}'),o={name:"executive-orders/2025-03-08-restoring-public-service-loan-forgiveness.md"};function l(n,e,a,c,u,g){return s(),r("div",null,e[0]||(e[0]=[t('<h1 id="restoring-public-service-loan-forgiveness" tabindex="-1">Restoring Public Service Loan Forgiveness <a class="header-anchor" href="#restoring-public-service-loan-forgiveness" aria-label="Permalink to &quot;Restoring Public Service Loan Forgiveness&quot;">​</a></h1><p>Published: Friday, March 7, 2025</p><h1 id="summary-of-executive-order-on-public-service-loan-forgiveness-pslf-program" tabindex="-1">Summary of Executive Order on Public Service Loan Forgiveness (PSLF) Program <a class="header-anchor" href="#summary-of-executive-order-on-public-service-loan-forgiveness-pslf-program" aria-label="Permalink to &quot;Summary of Executive Order on Public Service Loan Forgiveness (PSLF) Program&quot;">​</a></h1><ul><li><p><strong>Authority</strong>: The President enacts this order under the Constitution and U.S. law.</p></li><li><p><strong>Background</strong>:</p><ul><li>PSLF Program was established in 2007 by Congress to incentivize public service jobs.</li><li>The program promises student loan forgiveness after 10 years of service and minimum payments.</li></ul></li><li><p><strong>Issues Identified</strong>:</p><ul><li>The previous administration abused the PSLF through a waiver process, misallocating taxpayer funds.</li><li>PSLF misdirects resources into activist organizations that undermine national security and American values.</li><li>The program potentially increases tuition costs and burdens students with unsuitable debt.</li></ul></li><li><p><strong>National Security</strong>:</p><ul><li>The President’s duty includes ending subsidies for illegal activities that threaten U.S. security, such as: <ul><li>Illegal immigration</li><li>Human smuggling</li><li>Child trafficking</li><li>Public property damage</li><li>Disruption of public order</li></ul></li></ul></li><li><p><strong>Policy Changes</strong>:</p><ul><li>Individuals employed by organizations with substantial illegal activities shall be ineligible for PSLF.</li></ul></li><li><p><strong>Definition Revisions</strong>:</p><ul><li>The Secretary of Education will propose changes to 34 C.F.R. 685.219 to redefine “public service” to exclude: <ul><li>Activities violating federal immigration laws.</li><li>Supporting terrorism or facilitating operations of designated cartels.</li><li>Child abuse or trafficking children to evade lawful parents.</li><li>Aiding and abetting illegal discrimination.</li><li>Violating state tort laws including trespassing, vandalism, and disorderly conduct.</li></ul></li></ul></li><li><p><strong>Legal Provisions</strong>:</p><ul><li>The order does not impair the authority of executive departments or the Office of Management and Budget.</li><li>It is subject to applicable laws and budget appropriations.</li><li>The order does not create enforceable rights against the U.S. or its entities.</li></ul></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/03/restoring-public-service-loan-forgiveness/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/03/restoring-public-service-loan-forgiveness/</a></p>',5)]))}const v=i(o,[["render",l]]);export{p as __pageData,v as default};
